-- 016 (round 8): music, remixes/duets, challenges, live gifts + coins, chat games, watch together,
-- stickers/custom emoji, streaks and badges. Additive only.
CREATE TABLE IF NOT EXISTS music_tracks (
  id BIGSERIAL PRIMARY KEY, provider TEXT NOT NULL DEFAULT 'bundled', external_id TEXT NOT NULL, title TEXT NOT NULL, artist TEXT NOT NULL,
  duration_seconds INT NOT NULL DEFAULT 0, url TEXT NOT NULL, license TEXT NOT NULL, source_url TEXT NOT NULL, mood TEXT NOT NULL DEFAULT '',
  active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (provider, external_id));
ALTER TABLE posts ADD COLUMN IF NOT EXISTS music_track_id BIGINT REFERENCES music_tracks(id) ON DELETE SET NULL;
ALTER TABLE posts ADD COLUMN IF NOT EXISTS music_start INT NOT NULL DEFAULT 0;
ALTER TABLE stories ADD COLUMN IF NOT EXISTS music_track_id BIGINT REFERENCES music_tracks(id) ON DELETE SET NULL;
ALTER TABLE posts ADD COLUMN IF NOT EXISTS remix_of_id BIGINT REFERENCES posts(id) ON DELETE SET NULL;
ALTER TABLE posts ADD COLUMN IF NOT EXISTS remix_layout TEXT;
ALTER TABLE posts ADD COLUMN IF NOT EXISTS effect TEXT;
CREATE TABLE IF NOT EXISTS challenges (id BIGSERIAL PRIMARY KEY, tag TEXT NOT NULL UNIQUE, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', music_track_id BIGINT REFERENCES music_tracks(id) ON DELETE SET NULL, created_by BIGINT REFERENCES users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), ends_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS coin_wallets (user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, balance BIGINT NOT NULL DEFAULT 0 CHECK (balance >= 0), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS coin_ledger (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, delta BIGINT NOT NULL, reason TEXT NOT NULL, ref TEXT NOT NULL DEFAULT '', by_user BIGINT REFERENCES users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS live_gifts (id BIGSERIAL PRIMARY KEY, stream_id BIGINT NOT NULL REFERENCES live_streams(id) ON DELETE CASCADE, sender_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, gift TEXT NOT NULL, coins INT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS chat_games (id BIGSERIAL PRIMARY KEY, conversation_id BIGINT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, kind TEXT NOT NULL, state JSONB NOT NULL DEFAULT '{}', created_by BIGINT NOT NULL REFERENCES users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS watch_sessions (conversation_id BIGINT PRIMARY KEY REFERENCES conversations(id) ON DELETE CASCADE, post_id BIGINT REFERENCES posts(id) ON DELETE SET NULL, position REAL NOT NULL DEFAULT 0, playing BOOLEAN NOT NULL DEFAULT false, updated_by BIGINT REFERENCES users(id) ON DELETE CASCADE, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS message_reactions (message_id BIGINT NOT NULL REFERENCES messages(id) ON DELETE CASCADE, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, emoji TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (message_id, user_id));
CREATE TABLE IF NOT EXISTS custom_emoji (id BIGSERIAL PRIMARY KEY, code TEXT NOT NULL UNIQUE, image_path TEXT NOT NULL, created_by BIGINT REFERENCES users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS activity_days (user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, day DATE NOT NULL, PRIMARY KEY (user_id, day));
CREATE TABLE IF NOT EXISTS user_badges (user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, badge TEXT NOT NULL, awarded_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (user_id, badge));
